-- pessimistic
START TRANSACTION;
SELECT points FROM customers WHERE id = 42 FOR UPDATE;
UPDATE customers SET points = points - 500 WHERE id = 42;
COMMIT;

-- optimistic
UPDATE customers
SET points = points - 500, version = version + 1
WHERE id = 42 AND version = 7;   -- 0 rows updated = someone changed it

-- DELETE: some rows, can be rolled back, fires triggers
START TRANSACTION;
DELETE FROM orders WHERE status = 'cancelled';
ROLLBACK;                         -- rows come back

